from lesson_helpers import *
from lesson_figures import figure,CSS
T=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-N05"><div class="chap"><div class="chap-head"><div class="code">N05 · N-07-Néphrologie</div><h1>Syndrome néphritique, sans précision</h1><span class="status">Monographie pédagogique · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#n05-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(T,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="N05">'''
a+=sec('question','Le dossier dit « néphrite » : que faut-il décider aujourd’hui ?', '''<p><b>Vignette fictive.</b> Une personne arrive avec un résultat de créatinine élevé, une hématurie et une protéinurie. Aucun résultat ancien n’est disponible. Depuis quelques jours, elle remarque des chevilles gonflées et urine moins. Le courrier mentionne simplement « néphrite, sans précision ». Ce libellé ne permet de conclure ni à une maladie récente, ni à une cicatrice ancienne, ni à une indication de corticoïdes.</p><p>Le premier examen recherche une complication : dyspnée, surcharge, hypertension avec retentissement, trouble du potassium ou dégradation rapide. En parallèle, il faut retrouver les valeurs antérieures, caractériser les urines et organiser la recherche de cause. Une incertitude diagnostique impose un plan explicite ; elle ne justifie pas une attente sans surveillance.</p>'''+key('Écrire séparément ce qui est observé, ce qui menace le patient et ce qui manque encore pour préciser le diagnostic.'),('EU-SYNDROMES','EU-IRA','CH-HUG-ORIENT'))
a+=sec(1,'1. Définition : un cadre à préciser', '''<p>Un syndrome glomérulaire est évoqué devant une protéinurie glomérulaire et/ou une hématurie, auxquelles peuvent s’associer hypertension, œdèmes et insuffisance rénale. La présentation néphritique fait rechercher particulièrement hématurie, baisse de filtration et rétention hydrosodée. Leur combinaison et leur vitesse d’apparition orientent la gravité et la cause ; tous les signes ne sont pas nécessairement présents au même moment.</p><p><b>« Sans précision » décrit une information insuffisante.</b> Il ne désigne pas une étiologie autonome et n’établit pas que la maladie soit bénigne. Une même première observation peut correspondre à une atteinte aiguë, une maladie ancienne découverte tardivement ou une aggravation sur maladie chronique. Le diagnostic doit progresser dès que la chronologie, le bilan ou le tissu le permettent.</p><p>La CIM-10-GM suisse N05 inclut notamment glomérulopathie, glomérulonéphrite ou néphrite sans autre indication. Elle distingue la maladie rénale sans précision avec une morphologie connue, et exclut la maladie rénale ou néphropathie sans précision sans lésion morphologique précisée, classée N28.9, ainsi que la néphrite tubulo-interstitielle sans précision N12. Toute créatinine élevée inexpliquée ne relève donc pas automatiquement de N05.</p><p>Le diagnostic clinique vient avant le code. La cause, la temporalité, les lésions, la fonction et les complications se documentent sur des axes complémentaires. Le nom administratif ne fournit aucun protocole thérapeutique commun à tous les patients.</p>''',('EU-SYNDROMES','CH-CIM','INT-CKD-DEF'))
a+=sec(2,'2. Épidémiologie : ne pas donner une fréquence à une information manquante', '''<p>Les sources retenues ne donnent pas d’incidence suisse directe du syndrome néphritique sans précision N05. Ce libellé dépend aussi du degré de précision des dossiers et du codage ; une fréquence de codes ne serait pas nécessairement celle d’une maladie biologique unique. Aucun chiffre de dialyse, d’insuffisance rénale aiguë ou de biopsie ne lui est substitué.</p><p>La SGN estime qu’environ un adulte sur dix en Suisse présente une maladie rénale chronique. Il s’agit d’un contexte de dépistage, non d’une estimation de N05. De même, une série européenne de biopsies sélectionne les personnes pour lesquelles un prélèvement a été réalisé : elle ne représente pas toutes les hématuries de la population.</p><p>La probabilité d’une cause change avec l’âge, les antécédents, la famille, les infections, les maladies auto-immunes, les expositions et l’évolution. Ces données guident les hypothèses sans remplacer les preuves. L’absence de taux national précis n’empêche ni la reconnaissance d’une urgence ni une enquête ciblée.</p>''',('CH-SGN-DEF','EU-SYNDROMES','CH-CIM'))
a+=sec(3,'3. Physiopathologie : un même signe, plusieurs mécanismes', '''<p>Le filtre normal associe endothélium, membrane basale et podocytes. Une lésion peut augmenter le passage d’albumine et d’érythrocytes vers l’urine. La morphologie des hématies et les cylindres apportent des indices de localisation ; ils n’identifient pas à eux seuls le mécanisme immunitaire ou la maladie causale.</p>'''+figure('podocytes')+'''<p>Les maladies glomérulaires peuvent associer dépôts, prolifération, altération structurale et cicatrices. Une baisse de filtration peut accompagner une lésion glomérulaire active, mais aussi une hypoperfusion, une obstruction ou une atteinte tubulaire associée. Une baisse du coefficient d’ultrafiltration ou de la pression utile à la filtration diminue le débit ; le résultat biologique final ne distingue pas seul ces mécanismes.</p><p>La rétention de sodium et d’eau contribue aux œdèmes, à la prise de poids et à l’hypertension. La baisse des capacités d’excrétion peut favoriser hyperkaliémie et acidose. Le retentissement clinique dépend de la rapidité, de l’intensité et du terrain ; la quantité de sang visible ne mesure pas cette gravité.</p><p>Le croissant est une lésion extracapillaire. Sur l’original PAS ci-dessous, la provenance rapporte une maladie anti-membrane basale démontrée par immunofluorescence ; cette démonstration ne se voit pas sur cette seule coloration. Un croissant n’identifie donc pas à lui seul toute l’étiologie, et une photographie ne mesure pas la vitesse de dégradation du patient.</p>'''+figure('crescent'),('NORMAL-FILTRE','EU-HISTO','EU-IRA','CH-HUG-DEF'))
a+=sec(4,'4. Démarche clinique : sécuriser, dater, localiser, expliquer', '''<p><b>Sécuriser.</b> Apprécier respiration, circulation, état neurologique, pression, volume et diurèse. Chercher potassium et troubles acido-basiques selon le contexte, avec ECG lorsqu’une insuffisance rénale aiguë est suspectée. Une complication menaçante appelle des soins hospitaliers et un avis spécialisé immédiat, sans attendre la cause finale.</p><p><b>Dater.</b> Retrouver les créatininémies, urines et pressions antérieures, les hospitalisations, les médicaments et les événements intercurrents. L’absence de résultat ancien n’est pas une preuve de début récent. Inversement, une maladie ancienne peut subir une aggravation aiguë. Les critères de maladie rénale chronique exigent au moins trois mois ; ce délai de définition n’est jamais un délai d’attente imposé aux soins.</p><p><b>Localiser.</b> Confirmer les hématies, quantifier albumine et protéines, examiner le sédiment et vérifier les conditions de recueil. Rechercher aussi une infection ou un obstacle selon le tableau. La présence d’un indice glomérulaire ne dispense pas de rechercher une cause associée.</p><p><b>Expliquer et organiser.</b> Orienter immunologie, recherche infectieuse, génétique et biopsie avec le néphrologue. La conclusion distingue confirmé, probable et encore inconnu. Préciser qui revoit le patient, quand seront contrôlées fonction et urines, et quels signes déclenchent un contact immédiat.</p>''',('CH-HUG-ORIENT','CH-SGN-REF','EU-IRA','INT-CKD-DEF','INT-GN-GENERAL'))
a+=sec(5,'5. Anamnèse : retrouver la chronologie et les indices de cause',table(['Domaine','Données recherchées','Conséquence'],[['Temps','Dates des premières anomalies ; derniers résultats normaux ; vitesse des changements','Distinguer aigu, chronique et aigu sur chronique sans supposer une durée.'],['Urines et volume','Sang visible, diurèse, œdèmes, poids, dyspnée','Évaluer retentissement ; couleur et mousse ne quantifient ni fonction ni protéines.'],['Signes systémiques','Purpura, arthralgies, fièvre, symptômes ORL ou respiratoires','Orienter infection, auto-immunité ou vascularite ; hémoptysie et atteinte rénale imposent urgence.'],['Infection','Foyer récent ou persistant, état général, exposition pertinente','Rechercher une cause infectieuse avant une stratégie immune non ciblée.'],['Famille','Hématurie, insuffisance rénale, âge de survenue, audition, yeux','Discuter maladie héréditaire et conseil spécialisé.'],['Produits pris','AINS, traitements prescrits, changements récents, plantes et compléments','Chercher néphrotoxicité, interaction, modification hémodynamique ou déplétion.'],['Maladies connues','Diabète, lupus, hépatite, gammapathie et diagnostic rénal antérieur','Une cause connue ne prouve pas qu’elle explique tout épisode nouveau.'],['Terrain','Grossesse, croissance, fragilité, alimentation, travail et accès aux soins','Adapter examens, traitements et plan de surveillance.']])+'''<p>Un dossier incomplet appelle une recherche active des anciens résultats avec le patient et les soignants concernés. Une mention « normal » sans date, analyte ou unité ne suffit pas. Les traitements effectivement pris peuvent différer de la dernière ordonnance ; cette différence peut expliquer une partie de l’évolution.</p>''',('EU-SYNDROMES','CH-HUG-ORIENT','EU-ALPORT-GEN','INT-CKD-DRUG'))
a+=sec(6,'6. Examen clinique : identifier le retentissement actuel', '''<p>Mesurer pression, fréquence cardiaque, poids et état d’hydratation, puis rechercher œdèmes et signes de congestion. Une dyspnée nécessite une appréciation respiratoire et une recherche de surcharge ou d’atteinte pulmonaire systémique. Une pression élevée se juge avec ses conséquences neurologiques, cardiaques et rénales ; la prise en charge d’une urgence ne se confond pas avec une cible de traitement prolongé.</p><p>Rechercher les indices guidés par l’anamnèse : purpura, atteinte articulaire, foyer infectieux, signes ORL, manifestations oculaires ou auditives, anomalies des voies urinaires. Un tableau pulmonaire–rénal possible exige une évaluation urgente. L’absence d’un signe extrarénal ne suffit pas à exclure une glomérulopathie.</p><p>L’œdème ne prouve pas que tout patient soit correctement perfusé ni qu’une perfusion ou une hausse de diurétique soit appropriée. L’examen, les pertes, les médicaments et la trajectoire se confrontent. Chez l’enfant, pression et croissance s’interprètent selon les références pédiatriques ; chez la personne âgée, fragilité, orthostatisme, chutes et nutrition modifient la tolérance des objectifs.</p><p>Pour un éventuel suivi chronique stable, utiliser une méthode tensionnelle reproductible. La SGN2025 propose une systolique120–129mmHg individualisée ; KDIGO2024 propose moins de120 en mesure standardisée lorsque toléré. Ces recommandations attribuées ne donnent pas une cible immédiate universelle devant un syndrome non précisé.</p>''',('CH-HUG-ORIENT','EU-SYNDROMES','EU-IRA','CH-SGN-PEC','INT-CKD-TX'))
a+=sec(7,'7. Syndromes et classifications : séparer les axes',table(['Axe','Repères','Ce qui reste à préciser'],[['Néphritique aigu','Quelques jours ; hématurie, rétention/HTA, protéinurie, insuffisance rénale et oligurie possibles','Cause, sévérité et complications.'],['Rapidement progressif','Dégradation rapide de fonction avec signes glomérulaires','Urgence néphrologique ; immunologie et tissu orientent la cause.'],['Glomérulaire chronique','Protéinurie persistante ± hématurie, HTA ou baisse de fonction','Preuve de durée, activité, cicatrices et risque.'],['Néphrotique associé','Chez l’adulte selonCUEN : protéines≥3g/j oug/g et albumine<30g/L','Risques et conduite propres ; œdème isolé insuffisant.'],['IRA','Créatinine et/ou diurèse dans une fenêtre de temps définie','Décrit fonction et gravité, non l’étiologie.'],['MRC','Atteinte≥3mois ; cause, catégoriesG etA','G1/G2 sans marqueur ne suffisent pas à définir la maladie.'],['Morphologie','Dépôts, prolifération, croissants, sclérose, distribution','Une lésion peut avoir plusieurs causes.']])+'''<p>N05 ne constitue pas un stade entre aigu et chronique. Il faut continuer à préciser le tableau à partir des preuves disponibles. Le suffixe morphologique ne résume ni le retentissement ni la vitesse d’évolution.</p><p>Si une MRC est établie, les catégories de débit sontG1≥90,G2 60–89,G3a45–59,G3b30–44,G4 15–29 etG5&lt;15mL/min/1,73m². L’albuminurieA1&lt;30,A2 30–300,A3&gt;300mg/g constitue un autre axe. Ces catégories ne servent pas à classer une valeur instable comme si l’équation donnait alors une mesure fiable de filtration.</p>''',('EU-SYNDROMES','EU-HISTO','INT-AKI','INT-CKD-DEF','EU-IRA'))
save('a',a)
b=sec(8,'8. Diagnostic positif : rendre les preuves et les incertitudes explicites', '''<p><b>Confirmer le signe.</b> Une bandelette positive pour le sang n’établit pas seule une hématurie ; vérifier la présence d’érythrocytes. Quantifier protéines et albumine dans les unités du laboratoire. Une dysmorphie supérieure à60%, des acanthocytes supérieurs à5% ou des cylindres hématiques orientent une origine glomérulaire selonHUG2024 ; sensibilité, recueil et lecture en limitent l’interprétation. Leur absence n’exclut pas une maladie glomérulaire.</p><p><b>Décrire la fonction avec le temps.</b> Dans la dernière directive AKI adoptée trouvée, reprise par le CUEN2025, l’IRA correspond à une hausse de créatinine≥26,5µmol/L en48h, ou≥1,5fois la valeur de base connue ou présumée en7jours, ou une diurèse&lt;0,5mL/kg/h pendant6h. Un de ces critères suffit. Ils ne diagnostiquent pas une glomérulonéphrite. Une dégradation plus lente peut rester grave sans remplir cette fenêtre.</p><p><b>Préciser le syndrome et la cause.</b> L’ensemble clinique et urinaire soutient la localisation ; les examens orientés et parfois la biopsie établissent la maladie. Une IgA sérique ne prouve pas une néphropathie àIgA ; le diagnostic est tissulaire. La génétique peut préciser une atteinteCOL4A3/COL4A4/COL4A5, avec ses limites et la possibilité d’une maladie associée.</p><p><b>Actualiser le diagnostic.</b> Documenter ce qui empêche encore une précision : antériorité absente, bilan en attente ou tissu non disponible. La page officielleKDIGO consultée présente encoreAKI/AKD2026 comme projet préparé pour publication ; il n’est pas utilisé ici comme directive adoptée.</p>''',('CH-HUG-DEF','CH-HUG-ORIENT','INT-AKI','INT-AKI-STATUS','EU-IRA','INT-IGA-DX','EU-ALPORT-GEN'))
b+=sec(9,'9. Explorations : une question pour chaque examen',table(['Examen','Question','Limite'],[['Créatinine, électrolytes, équilibre acido-basique, ECG selon contexte','Retentissement et complications immédiates ?','Un chiffre isolé ne date ni ne localise la maladie.'],['Urines et sédiment','Hématies réelles, morphologie, cylindres, albumine/protéines ?','Méthode, fraîcheur, contamination et variabilité.'],['Échographie rénale et voies urinaires','Obstacle ou anomalie structurale ? Indices de chronicité ?','Ne montre pas les dépôts glomérulaires microscopiques.'],['Immunologie orientée','Complément,ANCA,anti-MBG,autoanticorps ou immunoglobuline monoclonale selon tableau ?','Ne constitue pas un panel diagnostique indépendant du contexte.'],['Recherche infectieuse','Foyer actif ou persistant susceptible d’expliquer/modifier le tableau ?','Choix guidé par histoire et examen.'],['Biopsie','Cause, activité, chronicité et conséquence thérapeutique ?','Échantillonnage, risques et techniques complémentaires.'],['Génétique','Phénotype familial ou structural évocateur ?','Variant incertain ou test négatif ne ferment pas toute hypothèse.']])+'''<p>La biopsie est encadrée par le néphrologue ; son intérêt diagnostique, pronostique et thérapeutique se confronte au risque. En cas de suspicion de glomérulonéphrite rapidement progressive, bilan immunologique et démarche tissulaire sont urgents. La prise en charge des complications avance en parallèle. Les délais d’arrêt d’un anticoagulant ou antiagrégant sont ceux du centre et de la situation, sans automatisme dérivé du codeN05.</p><p>Les microscopies optique, immunofluorescente et électronique répondent à des questions distinctes. Un pattern membranoprolifératif oriente une recherche d’infection, auto-immunité, immunoglobuline monoclonale ou complément selon le profil. Un complément normal ne ferme pas toutes les causes ; une valeur basse ne donne pas une étiologie unique.</p>''',('EU-IRA','EU-SYNDROMES','EU-HISTO','INT-GN-GENERAL','INT-GN-MPGN','EU-ALPORT-GEN'))
b+=sec(10,'10. Arbre diagnostique : avancer malgré l’information manquante',table(['Étape','Décision','Suite'],[['1. Complication ou accélération ?','Dyspnée, oligurie, retentissement hypertensif, potassium/acidose, signes systémiques','Sécurisation et avis urgent ; ne pas attendre le résultat final.'],['2. Anomalie réelle ?','Recueil, hématies, protéines/albumine et unités','Corriger une erreur préanalytique tout en évaluant la gravité réelle.'],['3. Compartiment glomérulaire ?','Sédiment, prédominance albuminurique, contexte','Confronter causes urologiques, tubulaires, interstitielles et vasculaires.'],['4. Quelle durée ?','Résultats anciens, trajectoire, imagerie/tissu','Aigu, chronique ou aigu sur chronique ; préciser si encore inconnu.'],['5. Quelle cause ?','Infection, auto-immunité/vascularite, dépôts, famille, médicaments','Examens orientés et tissu/génétique lorsque utile.'],['6. Quel plan ?','Cause certaine/probable, activité, risques, préférences','Traitement adapté et contrôle daté ; réviser le libellé quand possible.']])+'''<p>Une hypoperfusion ou une obstruction peut expliquer une part de la baisse de fonction, même si une hématurie est présente. Une leucocyturie n’établit pas seule une infection, et un cylindre leucocytaire ne nomme pas une glomérulonéphrite. Diabète ou hypertension connus n’expliquent pas automatiquement un sédiment actif, un purpura ou une dégradation atypique.</p><p>La discordance est utile : un résultat qui ne correspond pas à l’hypothèse initiale impose de rouvrir les possibilités plutôt que de conserver N05 comme explication définitive. Une infection active et une maladie immune peuvent exiger des stratégies très différentes.</p>''',('EU-IRA','EU-SYNDROMES','CH-HUG-URO','CH-HUG-ORIENT','INT-GN-MPGN','EU-ALPORT-GEN'))
b+=sec(11,'11. Prise en charge : traiter le risque actuel et préciser la cause', '''<p><b>Urgence.</b> Une suspicion de syndrome pulmonaire–rénal, une baisse rapide de fonction ou une complication menaçante relève d’une prise en charge hospitalière spécialisée. Rechercher et traiter hyperkaliémie, acidose, surcharge et trouble hémodynamique selon protocoles adaptés. L’épuration extrarénale est urgente si les troubles hydriques, électrolytiques ou acido-basiques menacent la vie ; le contexte et la tendance comptent davantage qu’un seuil isolé de créatinine.</p><p><b>Volume et pression.</b> La stratégie dépend de l’état réel : une personne déplétée et une personne congestive ne reçoivent pas le même traitement. Le furosémide peut traiter une surcharge dans son cadre d’indication ; il ne répare pas le filtre ni ne remplace une suppléance nécessaire. Les dosesIV deLasix proviennent de la FI de l’ampoule, distincte de celle du comprimé. Le traitement d’une urgence hypertensive ne se déduit pas du schéma oral d’amlodipine.</p><p><b>Cause.</b> Infection, auto-immunité, maladie à dépôts ou maladie héréditaire nécessitent des démarches différentes. Aucune immunosuppression systématique n’est prescrite sur le seul nomN05. La suspicion de maladie active grave appelle une décision spécialisée rapide ; l’incertitude ne doit devenir ni une prescription aveugle ni une raison d’inaction.</p><p><b>Après stabilisation.</b> Si une MRC est établie, discuter néphroprotection selon cause, albuminurie, fonction et tolérance. Le guideSGN2025 et lesFI exactes guidentIEC/ARA, contrôle tensionnel et éventueliSGLT2. Le seuil de classeSGLT2 de20 ne remplace pas la limite d’introductionForxiga à25mL/min/1,73m² ; la FI ne recommande pas le produit pour une néphropathie sous immunosuppresseur. RevoirAINS, interactions, grossesse et risque de déplétion. Une pause médicamenteuse doit comporter un contrôle et un plan de reprise.</p>''',('EU-IRA','INT-AKI','CH-SGN-PEC','INT-CKD-TX','INT-CKD-DRUG','FI-LASIX-IV','FI-LASIX-PO','FI-NORVASC','FI-RAMIPRIL','FI-COSAAR','FI-FORXIGA'))
b+=sec(12,'12. Prévention, suivi et pronostic : ne pas perdre un patient encore non classé', '''<p>Le premier suivi doit répondre aux incertitudes qui ont motivé le libellé : retrouver les données, vérifier l’évolution fonctionnelle et urinaire, obtenir les examens en attente et préciser le diagnostic. L’intervalle dépend de la gravité et de la vitesse, non du seul mot « sans précision ». Oligurie, dyspnée, hémoptysie, signes neurologiques ou aggravation clinique imposent un contact anticipé.</p><p>Le pronostic dépend de la cause, de l’activité, des cicatrices, de la fonction, des protéines et de la réponse. Un champ histologique ou un résultat ponctuel ne donne pas une trajectoire individuelle certaine. Après une atteinte aiguë, rechercher récupération et séquelles ; si des anomalies persistent au moins trois mois, vérifier les critères et le classement de MRC. L’amélioration de la diurèse n’établit pas seule la guérison.</p><p>Dans une MRC confirmée, suivre débit et albuminurie au moins annuellement, plus souvent si le risque ou un changement thérapeutique le demande. Les variations de débit supérieures à20%, ou à30% après une thérapie hémodynamique, et un doublement de l’ACR appellent une évaluation. Ces repères de suivi ne doivent pas retarder les soins d’une aggravation aiguë. Les équations de risque validéesG3–G5 ne se transposent pas à une fonction instable ou àG1/G2.</p><p>Prévention et éducation associent revue des produits pris, surveillance adaptée, contrôle tensionnel et mesures de mode de vie lorsque le cadre est stable. Les objectifs alimentaires sont individualisés : pas de restriction protéique adulte automatique chez l’enfant, la personne fragile ou une situation aiguë. Le patient doit comprendre le prochain examen et le professionnel à contacter.</p>''',('EU-IRA','EU-HISTO','INT-CKD-DEF','INT-CKD-RISK','INT-CKD-TX','CH-SGN-REF','INT-CKD-DRUG'))
b+=sec(13,'13. Points clés pour l’examen fédéral', '''<p>Présenter une synthèse en quatre phrases : syndrome observé ; gravité et trajectoire ; hypothèses causales ; plan immédiat et suivi. Dire ce qui manque permet une décision transparente. Il faut savoir expliquer pourquoi le bilan doit être urgent ou pourquoi un contrôle ambulatoire organisé est possible dans la situation donnée.</p><p>DansPROFILES2017, l’hématurie se relie àSSP64 ; les tâches159,161,164 et173 concernent notamment tissu/génétique, fonction rénale, sédiment et protéinurie. Les directivesMEBEKO2026 articulent connaissances et compétences cliniques. Les cas et quiz ci-dessous sont des exercices originauxMEDINA, sans statut de questions officielles.</p><p>Une réponse utile associe toujours test et conséquence : sédiment pour localiser, créatinine datée pour apprécier la trajectoire, échographie pour rechercher un obstacle, immunologie orientée et tissu pour préciser une cause. Le code apparaît après cette conclusion clinique.</p><p>'''+''.join(w('cas-'+str(i),'Cas clinique '+str(i))+' ' for i in range(1,5))+'''</p>''',('CH-PROFILES','CH-MEBEKO','CH-HUG-ORIENT','EU-IRA'))
b+=sec(14,'14. Pièges : ce que le libellé ne permet pas de conclure',table(['Raccourci','Correction','Conséquence'],[['Sans précision = bénin','La précision du dossier et la gravité sont indépendantes','Évaluer les complications dès le premier contact.'],['Créatinine élevée = néphriteN05','Fonction, localisation et nomenclature sont distinctes','Chercher obstacle,hypoperfusion et autres compartiments.'],['Pas d’antériorité = aigu','Le début est inconnu','Retrouver les données et surveiller la trajectoire.'],['Attendre trois mois pour agir','Trois mois définit laMRC','Traiter une menace actuelle immédiatement.'],['Croissant = anti-MBG','Plusieurs mécanismes produisent ce pattern','Confronter immunologie et techniques tissulaires.'],['Corticoïdes pour toute néphrite','Traitement causal et risques différents','Décision spécialisée adaptée, notamment à l’infection.'],['Plus d’urines = rein guéri','La diurèse ne mesure pas toutes les fonctions','Suivre fonction,volume et électrolytes.'],['Dose d’une forme = dose de toute forme','FIproduit et voie exactes','LasixIVmars2025 et oralmai2025 distingués.'],['Projet2026 = directiveadoptée','Statut officiel vérifié séparément','Attribuer le référentiel utilisé.']])+key('Le bon diagnostic provisoire contient déjà un plan pour réduire l’incertitude.'),('CH-CIM','EU-IRA','INT-AKI','INT-AKI-STATUS','EU-HISTO','FI-LASIX-IV','FI-LASIX-PO'))
b+='</div></div>'
save('b',b)
